#include "software_device.hpp"
#include <cassert>
int main(){using namespace soft;Renderer r;SoftwareDevice d(r);Camera camera;camera.position={0,0,0};d.begin(camera);rw::SetRenderState(rw::ALPHATESTFUNC,rw::ALPHAALWAYS);rw::SetRenderState(rw::CULLMODE,rw::CULLNONE);auto g=rw::Geometry::create(4,2,rw::Geometry::POSITIONS|rw::Geometry::PRELIT|rw::Geometry::MODULATE);for(int i=0;i<2;++i){auto mat=rw::Material::create();mat->color={140,170,210,255};g->matList.appendMaterial(mat);mat->destroy();}g->triangles[0]={{0,1,2},0};g->triangles[1]={{2,1,3},1};rw::V3d positions[4]={{-2,-2,5},{2,-2,5},{-2,2,5},{2,2,5}};for(unsigned i=0;i<4;++i){g->morphTargets[0].vertices[i]=positions[i];g->colors[i]={uint8_t(70+i*40),uint8_t(220-i*40),120,255};}auto a=rw::Atomic::create();a->setGeometry(g,0);
for(unsigned test=0;test<3;++test){if(test==1)g->matList.materials[1]->color={240,80,100,255};if(test==2)g->matList.materials[0]->color=g->matList.materials[1]->color;r.clear(0);a->render();auto image=r.pixels();auto depth=r.depth();r.clear(0);for(unsigned t=0;t<2;++t){rw::cpu::Im3DVertex v[3];auto tri=g->triangles[t];auto tint=g->matList.materials[t]->color;for(unsigned j=0;j<3;++j){auto color=g->colors[tri.v[j]];v[j].position=positions[tri.v[j]];v[j].setColor(unsigned(color.red)*tint.red/255,unsigned(color.green)*tint.green/255,unsigned(color.blue)*tint.blue/255,255);}rw::im3d::Transform(v,3,nullptr,rw::im3d::EVERYTHING);rw::im3d::RenderPrimitive(rw::PRIMTYPETRILIST);rw::im3d::End();}assert(image==r.pixels()&&depth==r.depth());}assert(d.reusedColors()==4);assert(!d.unsupported());a->destroy();g->destroy();d.end();}
